def initialize(self) -> None:
    if self.initialized or self.closed:
        raise RuntimeError("transport cannot be initialized again")
    # Worker isolation: register the NPU backend in runtime processes only.
    import torch_npu  # noqa: F401

    torch.npu.set_device(self.local_device)
    try:
        self.control_group = self._create_group("gloo", "afd_hccl_v3_control")
        self._hello()
        for stage_idx in range(self.negotiated_capabilities.max_stages):
            self.data_groups.append(
                self._create_group("hccl", f"afd_hccl_v3_stage_{stage_idx}")
            )
        self.initialized = True
    except BaseException:
        self.terminal = True
        with suppress(Exception):  # Preserve the initialization exception.
            self.close()
        raise

def send_layer_output(
    self, layer_idx: int, stage_idx: int, output: torch.Tensor
) -> None:
    self._require_active("ffn")
    peers = self._require_step(layer_idx, stage_idx)
    if self._pending_inputs is None:
        raise RuntimeError("receive all aggregate inputs before sending outputs")
    rows = sum(peer.padded_tokens for peer in peers)
    self._check_tensor(
        output, (rows, self.negotiated_capabilities.hidden_size), torch.bfloat16
    )
    try:
        for peer in peers:
            start, stop = peer.ffn_offset, peer.ffn_offset + peer.padded_tokens
            dist.send(
                output[start:stop],
                group_dst=peer.attention_world_rank,
                group=self.data_groups[stage_idx],
            )
        self._advance()
    except BaseException:
        self.terminal = True
        raise

def _send_tensor(
    self,
    tensor: torch.Tensor,
    *,
    dst: int,
    group: ProcessGroup,
    stream=None,
) -> None:
    # Dynamo marks the MTP token dimension dynamic. Querying contiguity in
    # Python specializes that dimension during full draft compilation even
    # though the model-owned buffers are already contiguous.
    send_tensor = (
        tensor
        if torch.compiler.is_compiling() or tensor.is_contiguous()
        else tensor.contiguous()
    )
    if stream is not None:
        self._record_stream(send_tensor, stream)
    if self._graph_transport_active():
        _graph_hccl_send(send_tensor, dst=dst, group=group)
        return
    dist.send(send_tensor, dst=dst, group=group)

def broadcast(self, tensor: torch.Tensor, src: int, stream=None):
    if self.disabled:
        return
    if not self.available:
        raise RuntimeError("HCCL communicator is closed")
    assert tensor.device == self.device, (
        f"this hccl communicator is created to work on {self.device}, but the input tensor is on {tensor.device}"
    )
    if stream is None:
        stream = current_stream()
    buffer = buffer_type(tensor.data_ptr())
    self.hccl.hcclBroadcast(
        buffer,
        tensor.numel(),
        hcclDataTypeEnum.from_torch(tensor.dtype),
        src,
        self.comm,
        aclrtStream_t(stream.npu_stream),
    )
